mapper.select:
select todayData.PRODID prodId, P.REG_CODE prdRegistCode, P.PRODNAME prodName, todayData.HOLD_DATE holdDate, todayData.CCY ccy, todayData.QTY qty, ifnull(lastDayData.QTY, 0) lastQty, todayData.sumCus, todayData.sumQty, todayData.QTY - ifnull(lastDayData.QTY, 0) changeQty from ( SELECT A.REGIST_BANK_CODE, A.PRODID,
A.HOLD_DATE, A.CCY, SUM(A.QTY) QTY, SUM(A.CNY_AMT) sumQty, COUNT(DISTINCT A.INDENTIFY_MARK) sumCus FROM CHB_INVESTHOLD_INFO A
#{item,jdbcType=VARCHAR}
AND DATE_FORMAT(A.HOLD_DATE,'%Y-%m-%d') >= #{holdDateStart,jdbcType=VARCHAR}
AND DATE_FORMAT(A.HOLD_DATE,'%Y-%m-%d') <= #{holdDateEnd,jdbcType=VARCHAR}
AND A.STATUS <> 'D'
GROUP BY A.REGIST_BANK_CODE,A.PRODID,A.HOLD_DATE,A.CCY
) todayData left join ( SELECT A.REGIST_BANK_CODE, A.PRODID,
A.HOLD_DATE, A.CCY, SUM(A.QTY) QTY FROM CHB_INVESTHOLD_INFO A
#{item,jdbcType=VARCHAR}
AND DATE_FORMAT(A.HOLD_DATE,'%Y-%m-%d') >= #{holdDateStartLastDay,jdbcType=VARCHAR}
AND DATE_FORMAT(A.HOLD_DATE,'%Y-%m-%d') <= #{holdDateEndLastDay,jdbcType=VARCHAR}
AND A.STATUS <> 'D'
GROUP BY A.REGIST_BANK_CODE,A.PRODID,A.HOLD_DATE,A.CCY
) lastDayData on todayData.REGIST_BANK_CODE = lastDayData.REGIST_BANK_CODE and todayData.PRODID = lastDayData.PRODID
AND todayData.HOLD_DATE - 1 = lastDayData.HOLD_DATE AND todayData.CCY = lastDayData.CCY
LEFT JOIN CHB_PRDRESIST_CODE P
ON todayData.PRODID = P.PRODID order by todayData.PRODID, todayData.HOLD_DATE, todayData.CCY
